  6→import * as React from 'react';
  7→
  8→import { type BannerVariant } from '../../containers/Banner/Banner.tsx';
  9→
 10→
 11→export type ToastId = string;
 12→export type ToastOptions = {
 13→  autoClose?: undefined | false | number /*ms*/, // Time after which to automatically close the toast
 14→  dedupeKey?: undefined | string, // Optional unique identifier used to deduplicate notifications
 15→};
 16→export type ToastDescriptor = {
 17→  variant: BannerVariant,
 18→  message: React.ReactNode,
 19→  title?: undefined | string,
 20→  options?: undefined | ToastOptions,
 21→};
 22→
 23→export type ToastStoreOptions = {
 24→  entryAnimationDelay?: number /*ms*/,
 25→  exitAnimationDelay?: number /*ms*/,
 26→  autoCloseDelay?: number /*ms*/, // Should be higher than `entryAnimationDelay`
 27→};
 28→export type ToastMetadata = {
 29→  openedAt: Date,
 30→  dismissed: boolean,
 31→  autoCloseTimer: null | Timer,
 32→};
 33→export type ToastWithMetadata = { metadata: ToastMetadata, descriptor: ToastDescriptor };
 34→export type ToastStorage = Readonly<Record<ToastId, ToastWithMetadata>>;
 35→export type ToastSubscriber = (this: ToastStore, toasts: ToastStorage) => void;
 36→
 37→/**
 38→ * Store for the currently active toasts. Can be subscribed to to get notified when the state changes.
 39→ */
 40→export class ToastStore {
 41→  #options: Required<ToastStoreOptions>;
 42→  
 43→  #idCounter = 0; // Maintain a count for automatic ID generation
 44→  #toasts: ToastStorage = Object.create(null);
 45→  #subscribers: Set<ToastSubscriber> = new Set();
 46→  #dedupeKeys: Set<string> = new Set(); // Tracks active dedupe keys to prevent showing duplicate notifications.
 47→  
 48→  constructor(options: ToastStoreOptions = {}) {
 49→    this.#options = {
 50→      entryAnimationDelay: options.entryAnimationDelay ?? 400,
 51→      exitAnimationDelay: options.exitAnimationDelay ?? 200,
 52→      autoCloseDelay: options.autoCloseDelay ?? 8000,
 53→    };
 54→  }
 55→  
 56→  toasts() { return { ...this.#toasts }; }
 57→  
 58→  /** Subscribe to updates on the store (observable pattern). Returns a function to unsubscribe. */
 59→  subscribe(subscriber: ToastSubscriber): () => void {
 60→    this.#subscribers.add(subscriber);
 61→    subscriber.call(this, this.#toasts); // Publish the current state
 62→    return () => {
 63→      this.#subscribers.delete(subscriber);
 64→    };
 65→  }
 66→  
 67→  /** Publish the current state to all subscribers. */
 68→  publish() {
 69→    for (const subscriber of this.#subscribers) {
 70→      subscriber.call(this, this.#toasts);
 71→    }
 72→  }
 73→  
 74→  uniqueId(): ToastId {
 75→    const id = this.#idCounter++;
 76→    if (this.#idCounter >= Number.MAX_SAFE_INTEGER - 1) {
 77→      this.#idCounter = 0;
 78→    }
 79→    return String(id);
 80→  }
 81→  
 82→  // Generate an object key from the given ID. We prefix the ID, to make sure the key is not number-like in order
 83→  // to enforce that the object entries are ordered by insertion.
 84→  keyFromId(toastId: ToastId) {
 85→    return `toast-${toastId}`;
 86→  }
 87→  idFromKey(toastKey: string): ToastId {
 88→    return toastKey.replace(/^toast-/, '');
 89→  }
 90→  
 91→  getToastById(toastId: ToastId): null | ToastWithMetadata {
 92→    const toastKey = this.keyFromId(toastId);
 93→    return this.#toasts[toastKey] ?? null;
 94→  }
 95→  
 96→  updateToastMetadata(toastId: ToastId, updater: (metadata: ToastMetadata) => ToastMetadata) {
 97→    const toast = this.getToastById(toastId);
 98→    if (!toast) { throw new Error(`Missing toast: ${toastId}`); }
 99→    
100→    this.#toasts = {
101→      ...this.#toasts,
102→      [this.keyFromId(toastId)]: { ...toast, metadata: updater(toast.metadata) },
103→    };
104→  }
105→
106→  // Returns true if the toast has a dedupeKey and it already exists in the set,
107→  // indicating that a duplicate toast should be suppressed.
108→  hasActiveDedupeKey(toast: ToastDescriptor) {
109→    return typeof toast.options?.dedupeKey !== 'undefined'
110→      ? this.#dedupeKeys.has(toast.options.dedupeKey)
111→      : false;
112→  }
113→
114→  addDedupeKey(toast: ToastWithMetadata) {
115→    const dedupeKey = toast.descriptor.options?.dedupeKey;
116→
117→    if (typeof dedupeKey !== 'undefined') {
118→      this.#dedupeKeys.add(dedupeKey);
119→    }
120→  }
121→
122→  deleteDedupeKey(toast: ToastWithMetadata) {
123→    const dedupeKey = toast.descriptor.options?.dedupeKey;
124→
125→    if (typeof dedupeKey !== 'undefined') {
126→      this.#dedupeKeys.delete(dedupeKey);
127→    }
128→  }
129→  
130→  dismissToast(toastId: ToastId) {
131→    const toastKey = this.keyFromId(toastId);
132→    const toast = this.getToastById(toastId);
133→    if (!toast) { return; } // If the toast doesn't exist (anymore), ignore
134→    
135→    // Note: make sure to do an immutable update, otherwise this may not cause a rerender downstream
136→    if (typeof toast !== 'undefined') {
137→      this.updateToastMetadata(toastId, metadata => ({ ...metadata, dismissed: true }));
138→      this.publish();
139→    }
140→    
141→    // Clean up garbage data after the exit animation has had a chance to complete
142→    window.setTimeout(() => {
143→      const toasts = { ...this.#toasts };
144→      delete toasts[toastKey];
145→      this.deleteDedupeKey(toast);
146→      this.#toasts = toasts;
147→      this.publish();
148→    }, this.#options.exitAnimationDelay);
149→  }
150→  
151→  dismissAllToasts() {
152→    for (const toastKey of Object.keys(this.#toasts)) {
153→      this.dismissToast(this.idFromKey(toastKey));
154→    }
155→  }
156→  
157→  scheduleClose(toastId: ToastId, closeDelay: number /*ms*/): Timer {
158→    return new Timer(() => { this.dismissToast(toastId); }, closeDelay);
159→  }
160→  
161→  announceToast(toastId: ToastId, toast: ToastDescriptor) {
162→    const toastKey = this.keyFromId(toastId);
163→    
164→    // Note: make sure to do an immutable update, otherwise this may not cause a rerender downstream
165→    const toasts = { ...this.#toasts };
166→    
167→    // Replace (and refresh) any existing toast with the same ID
168→    if (Object.hasOwn(this.#toasts, toastId)) {
169→      delete toasts[toastKey];
170→    }
171→    
172→    // Schedule autoclose, if configured
173→    let autoCloseTimer: null | Timer = null;
174→    const autoCloseDelay: false | number = toast.options?.autoClose ?? this.#options.autoCloseDelay;
175→    if (autoCloseDelay && autoCloseDelay > 0) {
176→      const autoCloseDelayMax = Math.max(autoCloseDelay, this.#options.entryAnimationDelay);
177→      autoCloseTimer = this.scheduleClose(toastId, autoCloseDelayMax);
178→    }
179→    
180→    // Add the new toast
181→    toasts[toastKey] = {
182→      metadata: { openedAt: new Date(), dismissed: false, autoCloseTimer },
183→      descriptor: toast,
184→    };
185→    
186→    this.addDedupeKey(toasts[toastKey]);
187→    this.#toasts = toasts;
188→    this.publish();
189→  }
190→  
191→  shouldSkipEntryAnimation(toastId: ToastId) {
192→    const toastKey = this.keyFromId(toastId);
193→    const toast = this.#toasts[toastKey];
194→    if (typeof toast === 'undefined') { return; }
195→    
196→    const isDismissed = toast.metadata.dismissed;
197→    const openedAt: Date = toast.metadata.openedAt;
198→    return !isDismissed && (Date.now() - openedAt.valueOf()) >= this.#options.entryAnimationDelay;
199→  }
200→  
201→  pauseAutoClose(toastId: ToastId) {
202→    const toastKey = this.keyFromId(toastId);
203→    const toast = this.#toasts[toastKey];
204→    if (typeof toast === 'undefined') { return; }
205→    
206→    const autoCloseTimer = toast.metadata.autoCloseTimer;
207→    autoCloseTimer?.pause(); // Pause the auto-close timer, if any
208→  }
209→  
210→  resumeAutoClose(toastId: ToastId) {
211→    const toastKey = this.keyFromId(toastId);
212→    const toast = this.#toasts[toastKey];
213→    if (typeof toast === 'undefined') { return; }
214→    
215→    const autoCloseTimer = toast.metadata.autoCloseTimer;
216→    autoCloseTimer?.resume(); // Resume the auto-close timer, if any
217→  }
218→  
219→  onPageVisible() {
220→    for (const toastKey of Object.keys(this.#toasts)) {
221→      this.resumeAutoClose(this.idFromKey(toastKey));
222→    }
223→  }
224→  
225→  onPageHide() {
226→    for (const toastKey of Object.keys(this.#toasts)) {
227→      this.pauseAutoClose(this.idFromKey(toastKey));
228→    }
229→  }
230→}
