23→  defaultChecked?: undefined | CheckboxState,
24→  
25→  /** The current state of the checkbox. If `undefined`, the component is considered uncontrolled. */
26→  checked?: undefined | CheckboxState,
27→  
28→  /** Callback for update events, will be called with the new state of the checkbox. */
29→  onUpdate?: undefined | ((checked: CheckboxState) => void),
30→};
31→
32→export type CheckboxLabeledProps = CheckboxProps & {
33→  label: React.ComponentProps<typeof Label>['label'],
34→  labelProps?: undefined | Partial<React.ComponentProps<typeof Label>>,
35→};
36→export const CheckboxLabeled = ({ label, labelProps = {}, ...props }: CheckboxLabeledProps) => {
37→  const isDisabled = props.disabled;
38→  return (
39→    <Label position="inline-end" label={label} {...labelProps}
40→      className={cx(
41→        cl['bk-checkbox-labeled'],
42→        { [cl['bk-checkbox-labeled--disabled']]: isDisabled },
43→        labelProps.className,
44→      )}
45→    >
46→      <Checkbox {...props}/>
47→    </Label>
48→  );
49→};
50→
51→/**
52→ * A checkbox control is a basic on/off toggle.
53→ */
54→export const Checkbox = Object.assign(
55→  (props: CheckboxProps) => {
56→    const { unstyled = false, onUpdate, ...propsRest } = props;
57→    
58→    const handleChange = React.useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
59→      onUpdate?.(event.target.checked);
60→    }, [onUpdate]);
61→    
62→    return (
63→      <input
64→        type="checkbox"
65→        {...propsRest}
66→        className={cx(
67→          'bk',
68→          { [cl['bk-checkbox']]: !unstyled },
69→          propsRest.className,
70→        )}
71→        onChange={mergeCallbacks([props.onChange, handleChange])}
72→      />
73→    );
74→  },
75→  {
76→    Labeled: CheckboxLabeled,
77→  },
78→);
