/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import * as React from 'react';
import { classNames as cx, type ClassNameArgument, type ComponentProps } from '../../../util/componentUtil.ts';
import { useScroller } from '../../../layouts/util/Scroller.tsx';

import cl from './Tabs.module.scss';


export { cl as TabsClassNames };

export type TabKey = string;

export type TabProps = ComponentProps<'div'> & {
  /** A unique identifier for this tab. */
  tabKey: string,
  /** The contents of the tab, when active. */
  children?: undefined | React.ReactNode,
  /** A render prop to render the tab. Overrides `children`, if set. */
  render?: undefined | (() => React.ReactNode),
  /** The title of this tab, to be shown in the tab trigger button. */
  title: React.ReactNode,
  /** Whether to hide this tab. If true, the tab trigger is not rendered at all. */
  hide?: undefined | boolean,
  /** A class name to set on the tab trigger button. */
  className?: undefined | ClassNameArgument,
  /** A class name to set on the tab panel content. */
  contentClassName?: undefined | ClassNameArgument,
  /** Any additional props to pass to the tab trigger button. */
  tabTriggerProps?: undefined | ComponentProps<'li'> & { [key: `data-${string}`]: string },
};
export const Tab = ({ children }: TabProps): React.ReactElement => {
  return children as React.ReactElement;
};
type TabElement = React.ReactElement<TabProps, React.FunctionComponent<typeof Tab>>;

export type TabsProps = ComponentProps<'div'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** Active key of tab. */
  activeKey?: undefined | string,

   /** The orientation of the tabs, either vertical or horizontal. Default: `"horizontal"`. */
  orientation?: undefined | 'horizontal' | 'vertical',

  /** Which visual variant to use. Default: 'primary'. */
  variant?: undefined | 'primary' | 'secondary',

  /** Callback executed when active tab is changed. */
  onSwitch: (tabKey: TabKey) => void,
};
/**
 * A tab component
 */
export const Tabs = (props: TabsProps) => {
  const {
    unstyled = false,
    variant = 'primary',
    orientation = 'horizontal',
    activeKey,
    children,
    onSwitch,
    ...propsRest
  } = props;
  const scrollerProps = useScroller();

  // Select the activeKey tab among the given list of tabs
  const getActiveTab = (tabs: Array<TabElement>) => {
    const activeTabs = tabs.filter(child => child.props.tabKey === activeKey);

    if (activeTabs.length === 0) { return null; }
    if (activeTabs.length > 1) { throw new TypeError(`Ambiguous active tab`); }

    return activeTabs[0];
  };

  type ActiveTabProps = Omit<TabProps, 'children' | 'tabKey' | 'title' | 'hide' | 'render'>;
  const getActiveTabProps = (tab: TabElement): ActiveTabProps => {
    const { children, tabKey, title, hide, render, tabTriggerProps, ...tabProps } = tab.props;
    return tabProps;
  };

  const renderActive = (tab: TabElement) => {
    let tabElement: React.ReactNode;
    if (typeof tab.props.render === 'function') {
      tabElement = tab.props.render();
    } else {
      tabElement = tab.props.children;
    }

    return tabElement;
  };

  // FIXME: this throws an error in Chromatic, since `child.type` is `undefined`
  // React.Children.forEach(children, (child: React.ReactNode) => {
  //   if (!React.isValidElement(child) || child?.type?.name !== 'Tab') {
  //     throw new TypeError(`Expected only children of type Tab, received ${child}: ${JSON.stringify(child?.type)}`);
  //   }
  // });

  const tabs = React.Children.toArray(children) as Array<TabElement>;
  const activeTab = getActiveTab(tabs);
  const activeTabProps: null | ActiveTabProps = (activeTab && getActiveTabProps(activeTab)) ?? null;

  return (
    <div
      {...propsRest}
      className={cx(
        'bk',
        [cl[`bk-tabs--${variant}`]],
        [cl[`bk-tabs--${orientation}`]],
        { [cl['bk-tabs']]: !unstyled },
        propsRest.className,
      )}
    >
      <ul
        {...scrollerProps}
        className={cx(
          cl['bk-tabs__switcher'],
          scrollerProps.className
        )}
        role="tablist"
      >
        {tabs.map(tab => {
          const { tabKey, hide, tabTriggerProps } = tab.props;

          if (hide) { return null; }

          const isActive = tabKey === activeKey;

          return (
            <li
              key={tabKey}
              role="tab"
              tabIndex={0}
              aria-selected={isActive}
              data-tab={tabKey}
              {...tabTriggerProps}
              className={cx(cl['bk-tabs__switcher__tab'], tabTriggerProps?.className)}
              onClick={() => { onSwitch(tab.props.tabKey); }} // FIXME: add a Button and use that instead
            >
              <span>{tab.props.title}</span>
              {/* Hidden duplicated title, used to prevent layout shifts on hover. */}
              <span aria-hidden className={cx(cl['bk-tabs__switcher__tab__hover-placeholder'])}>{tab.props.title}</span>
            </li>
          );
        })}
      </ul>

      {activeTab &&
        <div
          role="tabpanel"
          {...(activeTabProps ?? {})}
          className={cx(
            cl['bk-tabs__tab-content'],
            activeTabProps?.contentClassName,
            activeTabProps?.className
          )}
        >
          {renderActive(activeTab)}
        </div>
      }
    </div>
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import * as React from 'react';
import { type ClassNameArgument, type ComponentProps, classNames as cx } from '../../../util/componentUtil.ts';

import { Icon } from '../../graphics/Icon/Icon.tsx';
import { Button } from '../../actions/Button/Button.tsx';

import cl from './Stepper.module.scss';


/*
References:
- https://stackoverflow.com/questions/52932018/making-a-step-progress-indicator-accessible-for-screen-readers
- https://www.telerik.com/design-system/docs/components/stepper/accessibility
- https://cauldron.dequelabs.com/components/Stepper
*/

export { cl as SteppersClassNames };

export type Step = {
  stepKey: string,
  title: React.ReactNode,
  className?: undefined | ClassNameArgument,
  hide?: undefined | boolean,
  isOptional?: undefined | boolean,
  isDisabled?: undefined | boolean,
};
export type StepperKey = Step['stepKey'];
export type StepperDirection = 'vertical' | 'horizontal';

export type StepperProps = React.PropsWithChildren<ComponentProps<'nav'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** Step items. */
  steps: Array<Step>,

  /** Active key of step. */
  activeKey?: undefined | string,

  /** Whether this component should be displayed vertically or horizontally. */
  direction?: undefined | StepperDirection,

  /** Callback executed when active step is changed. */
  onSwitch: (stepKey: StepperKey) => void,
}>;
/**
 * A stepper component
 */
export const Stepper = (props: StepperProps) => {
  const { unstyled = false, steps = [], activeKey, direction = 'vertical', onSwitch, ...propsRest } = props;

  return (
    <nav
      aria-label="Steps" // Recommendation is to override this per usage
      {...propsRest}
      className={cx(
        'bk',
        { [cl['bk-stepper']]: !unstyled },
        { [cl['bk-stepper--horizontal']]: direction === 'horizontal' },
        { [cl['bk-stepper--vertical']]: direction === 'vertical' },
        propsRest.className,
      )}
    >
      <ol>
        {steps.map((step, index) => {
          if (step.hide) { return null; }

          const isActive = step.stepKey === activeKey;
          const stepNumber = index + 1;
          const isChecked = index < steps.findIndex(step => step.stepKey === activeKey);
          const isDisabled = step.isDisabled ?? false;

          return (
            <li key={step.stepKey} aria-current={isActive ? 'step' : undefined}>
              <Button
                unstyled
                nonactive={isDisabled} // Note: disabled steps should still be focusable, so use `nonactive` here
                className={cx(
                  cl['bk-stepper__item'],
                  { [cl['bk-stepper__item--checked']]: isChecked },
                  { [cl['bk-stepper__item--disabled']]: isDisabled },
                  step.className,
                )}
                onPress={() => { onSwitch(step.stepKey); }}
              >
                <span className="visually-hidden">Step {stepNumber}{isChecked && ' (checked)'}</span>
                <span className={cx(cl['bk-stepper__item__indicator'])} aria-hidden="true">
                  {isChecked
                    ? <Icon icon="check" className={cx(cl['bk-stepper__item__indicator__icon'])}/> 
                    : stepNumber
                  }
                </span>
                <span className={cx(cl['bk-stepper__item__title'])}>{step.title}</span>
                {step.isOptional && <span className={cx(cl['bk-stepper__item__optional'])}>(Optional)</span>}
              </Button>
            </li>
          )
        })}
      </ol>
    </nav>
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import * as React from 'react';
import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import { useScroller } from '../../../layouts/util/Scroller.tsx';

import { Icon } from '../../graphics/Icon/Icon.tsx';

import cl from './Disclosure.module.scss';


export { cl as DisclosureClassNames };
export type DisclosureProps = Omit<ComponentProps<'details'>, 'title'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** The title of the disclosure. */
  title: React.ReactNode,

  /** Additional props for the <summary> element. */
  summaryProps?: undefined | Omit<ComponentProps<'summary'>, 'children'>,

  /** Additional props for the details content. */
  contentProps?: undefined | Omit<ComponentProps<'div'>, 'children'>,
};
/**
 * A disclosure, i.e. a collapsible container.
 */
export const Disclosure = (props: DisclosureProps) => {
  const { unstyled = false, title, summaryProps = {}, contentProps = {}, children, ...propsRest } = props;

  // Note: we need to apply `overflow-y: auto` dynamically, so do not apply scroller styling here
  const scrollerProps = useScroller({ includeStyling: false });

  /*
  Some notes on accessibility of `<details>`:
  - https://www.scottohara.me/blog/2022/09/12/details-summary.html (2022)
  - https://www.hassellinclusion.com/blog/accessible-accordions-part-2-using-details-summary (2019)
  - https://a11ysupport.io/tech/html/summary_element
  */

  return (
    <details
      {...propsRest}
      className={cx(
        { bk: true },
        { [cl['bk-disclosure']]: !unstyled },
        propsRest.className,
      )}
    >
      <summary {...summaryProps} className={cx(summaryProps.className)}>
        <span className={cl['bk-disclosure__title']}>
          {title}
        </span>
        <Icon icon="caret-down" className={cl['bk-disclosure__collapse-icon']}/>
      </summary>
      <div
        {...scrollerProps}
        {...contentProps}
        className={cx(cl['bk-disclosure__content'], contentProps.className)}
      >
        {children}
      </div>
    </details>
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import * as React from 'react';

import { ButtonAsLink } from '../../actions/ButtonAsLink/ButtonAsLink.tsx';

import cl from './Property.module.scss';

export type PropertySize = 'small' | 'medium' | 'large' | 'full-size';

type PropertyProps = ComponentProps<'div'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** The label of the property */
  label: null | React.ReactNode,

  /** The value of the property */
  value: null | React.ReactNode,

  /** 
   * Size of the property 
   * 
   * * Defaults to `small`.
  */
  size?: undefined | PropertySize

  /**
   * Enables multi-line clamping for string values.
   * When enabled, the text will be truncated to the specified number of lines
   * and an "View more / View less" toggle will be rendered to next line if overflow occurs.
   *
   * Only applies when `value` is a string.
   * Defaults to false.
   */
  expandable?: undefined | boolean,
  /**
   * Number of visible lines before truncation occurs.
   *
   * Only effective when `expandable` is true.
   * Defaults to 4.
   */
  clampLines?: undefined | number,
};

export const Property = (props: PropertyProps) => {
  const {
    unstyled,
    label,
    value,
    size = 'small',
    expandable = false,
    clampLines = 4,
    style,
    ...propsRest
  } = props;

  const [toggleExpanded, setToggleExpanded] = React.useState(false);

  const isStringValue = typeof value === 'string';

  const shouldClamp = expandable && isStringValue && !toggleExpanded;

  // Note: HTML allows wrapping dt/dd pairs in a `<div>`:
  // https://developer.mozilla.org/en-US/docs/Web/HTML/Element/dl#wrapping_name-value_groups_in_div_elements
  return (
    <div
      {...propsRest}
      className={cx(
        {
          [cl['bk-property']]: !unstyled,
          [cl['bk-property--small']]: size === 'small',
          [cl['bk-property--medium']]: size === 'medium',
          [cl['bk-property--large']]: size === 'large',
          [cl['bk-property--full-size']]: size === 'full-size',
        },
        propsRest.className,
      )}
      style={style}
    >
      <dt>{label}</dt>

      <dd>
        {/* Text wrapper (ONLY value gets clamped) */}
        <div
          className={cx(
            cl['bk-property__value'],
            {
              [cl['bk-property__value--clamped']]: shouldClamp,
            },
          )}
          style={shouldClamp ? { WebkitLineClamp: clampLines } : undefined}
        >
          {value}
        </div>

        {expandable && isStringValue && (
          <ButtonAsLink
            onPress={() => { setToggleExpanded(prev => !prev); }}
            className={cl['bk-property__toggle-expand']}
          >
            {toggleExpanded ? 'View less' : 'View more'}
          </ButtonAsLink>
        )}
      </dd>
    </div>
  );
};

